import{_ as e,o as n,c as s,ah as i}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Parents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/parents.md","filePath":"src/en/guide/secretariat/parents.md"}'),r={name:"en/guide/secretariat/parents.md"};function a(o,t,h,l,d,c){return n(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="parents" tabindex="-1">Parents <a class="header-anchor" href="#parents" aria-label="Permalink to &quot;Parents&quot;">​</a></h1><p>The <strong>Parents</strong> page, in the <strong>Students &amp; admissions</strong> space, gathers the students&#39; parents: their contact details, their children and where their account stands. It is mostly used to fill in missing e-mail addresses and phone numbers, then to invite the parents into the application.</p><p>It is open to the administration and the secretariat. The administration sees every parent. The secretariat sees the parents of the students enrolled on <strong>its site</strong>, the one on its employee profile. A secretariat member with no site on their profile sees every parent.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Children are not linked to a parent from this page: that is still done from the student&#39;s record, under <strong>Guardians</strong>, by the administration.</p></div><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Each row shows the parent, their e-mail address, their children with their class for the year (series and site included), their phone and where their account stands:</p><ul><li><strong>No e-mail</strong>: the parent has no e-mail address yet. This is the case for parents brought over from the previous platform without one. They cannot be invited until it is entered.</li><li><strong>Not invited</strong>: the address is known, no invitation has been sent.</li><li><strong>Invited</strong>: an invitation was sent and its link still works.</li><li><strong>Invitation expired</strong>: the link expired before the parent used it.</li><li><strong>Activated</strong>: the parent has chosen their password.</li></ul><p>To find a parent, type their name, address, phone or the name of one of their children, then click <strong>Search</strong>. The <strong>All statuses</strong> and <strong>All sites</strong> lists (when you see several sites) filter the list.</p><p><strong>Export as CSV</strong> downloads the list as filtered. With the <strong>No e-mail</strong> filter, it is the list of families to call for their address.</p><h2 id="correcting-the-contact-details" tabindex="-1">Correcting the contact details <a class="header-anchor" href="#correcting-the-contact-details" aria-label="Permalink to &quot;Correcting the contact details&quot;">​</a></h2><p>Click <strong>Edit</strong> at the end of the row.</p><ol><li>Correct the <strong>Name</strong>, <strong>E-mail address</strong> or <strong>Phone</strong>. The phone is written with the country code, for example +228 90 11 22 33.</li><li>For a parent without an e-mail, leave the field empty until you have their address: they keep their <strong>No e-mail</strong> status.</li><li>Fill in, when known, the <strong>Civility</strong> (Mr., Mrs., Miss), <strong>Profession</strong>, <strong>Nationality</strong> and <strong>P.O. box</strong>. The civility precedes the parent&#39;s name on the Traditional report card; all four fields are also in the CSV export.</li><li>Click <strong>Save changes</strong>.</li></ol><p>As soon as a real address is saved, the parent becomes <strong>Not invited</strong> and can be invited. Changing the address of an account not yet activated cancels the invitation already sent, since it went to the old address.</p><p>The <strong>Children</strong> section lists their children and their class. The administration finds a link there to the <strong>Student&#39;s guardians</strong>.</p><h2 id="inviting-the-parent" tabindex="-1">Inviting the parent <a class="header-anchor" href="#inviting-the-parent" aria-label="Permalink to &quot;Inviting the parent&quot;">​</a></h2><p>In the <strong>Access to the application</strong> section:</p><ul><li><strong>Send the invitation</strong> e-mails the parent a link to choose their password. The link stays valid for 7 days. For a parent already invited, the button becomes <strong>Resend the invitation</strong>, and the new link replaces the old one.</li><li><strong>Copy an invitation link</strong>, if the e-mail does not arrive: the link is shown and copied, to hand to the parent another way. It replaces the one sent by e-mail.</li></ul><p>A parent who has activated their account no longer needs an invitation: if they forget their password, they use <strong>Forgot password</strong> on the sign-in page.</p>',18)])])}const u=e(r,[["render",a]]);export{g as __pageData,u as default};
